function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });

const DELETED = ['D00092','D00109','D00140','D00143','D00773','D00810','D00969','D01055','D01060','D01110','D01156','D01553','D01606','D01658','D01671','D01840','D01870','D02015','D02048','D02136','D02240','D02244','D02303','D02615','D02665','D02750','D02761','D02784','D02873','D02896','D03008','D03010'];
const PAUSED6 = ['D00021','D00664','D01709','D01774','D02484','D02511'];

const ids = {}, byId = {};
for (const r of rows) { const d = s(r.deal_id); if (d) { ids[d] = (ids[d] || 0) + 1; byId[d] = r; } }
const stillPresent = DELETED.filter(function (d) { return !!ids[d]; });
const notPaused = PAUSED6.filter(function (d) { return !byId[d] || s(byId[d].pause) === ''; });

// ---- weekly send rate, from date_shared on sent rows ----
function weekKey(d) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(d);
  if (!m) { return null; }
  const dt = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  const day = (dt.getUTCDay() + 6) % 7;              // Mon=0
  dt.setUTCDate(dt.getUTCDate() - day + 3);          // Thursday of that week
  const firstThu = new Date(Date.UTC(dt.getUTCFullYear(), 0, 4));
  const fday = (firstThu.getUTCDay() + 6) % 7;
  firstThu.setUTCDate(firstThu.getUTCDate() - fday + 3);
  const wk = 1 + Math.round((dt - firstThu) / 604800000);
  return dt.getUTCFullYear() + '-W' + (wk < 10 ? '0' + wk : wk);
}

const perWeek = {};
let sentTotal = 0;
const allStartups = {};
for (const r of rows) {
  if (s(r.startup)) { allStartups[s(r.startup)] = 1; }
  if (s(r.deal_shared).toLowerCase() !== 'yes') { continue; }
  sentTotal++;
  const d = s(r.date_shared) || s(r.last_contact);
  const w = weekKey(d);
  if (!w) { continue; }
  if (!perWeek[w]) { perWeek[w] = { sends: 0, startups: {} }; }
  perWeek[w].sends++;
  perWeek[w].startups[s(r.startup)] = 1;
}

const weeks = Object.keys(perWeek).sort();
const weekly = weeks.map(function (w) {
  const n = perWeek[w].sends;
  const st = Object.keys(perWeek[w].startups).length;
  return { week: w, sends: n, startups_touched: st,
           avg_per_touched_startup: Math.round(n / st * 10) / 10,
           avg_per_all_60_startups: Math.round(n / 60 * 10) / 10 };
});

return [{ json: {
  VERDICT: (stillPresent.length === 0 && notPaused.length === 0) ? 'PASS' : 'CHECK',
  total_rows_now: rows.length,
  expected_2903: rows.length === 2903,
  deleted_still_present: stillPresent,
  six_not_paused: notPaused,
  sent_rows_total: sentTotal,
  distinct_startups_in_pipeline: Object.keys(allStartups).length,
  weekly_send_rate: weekly
}}];
